function validate([n, time]) {
  if (!Number.isInteger(n) || n < 2 || n > 1000) return 'n is an integer from 2 to 1000.';
  if (!Number.isInteger(time) || time < 1 || time > 1000) return 'time is an integer from 1 to 1000.';
  return null;
}

